A.CommandWorkbook[".go gameobject"]={group="지정 위치로 이동",name="guid #object_guid를 사용하여 캐릭터를 게임 개체로 순간 이동합니다",feature="guid #object_guid를 사용하여 캐릭터를 게임 개체로 순간 이동합니다.",method=".go gameobject #object_guid"}
