A.CommandWorkbook[".lfg group"]={group="파티 찾기(LFG)",name="그룹의 모든 플레이어에 대한 정보를 표시합니다(상태",feature="그룹의 모든 플레이어에 대한 정보를 표시합니다(상태, 역할, 댓글, 선택한 던전).",method=".lfg group"}
