A.CommandWorkbook[".unban character"]={group="차단 해제",name="캐릭터 이름 패턴에 대한 계정 금지 해제",feature="캐릭터 이름 패턴에 대한 계정 금지를 해제합니다.",method=".unban character $Name"}
